65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Dedicated audit logger. On a successful owner create an audit line carrying the owner id,
76	     * the {@code customerCode} and the {@code registrationDate} is emitted to this named logger.
77	     */
78	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper) {
92	        this.clinicService = clinicService;
93	        this.ownerMapper = ownerMapper;
94	        this.petMapper = petMapper;
95	        this.visitMapper = visitMapper;
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
101	        Collection<Owner> owners;
102	        if (lastName != null) {
103	            owners = this.clinicService.findOwnerByLastName(lastName);
104	        } else {
105	            owners = this.clinicService.findAllOwners();
106	        }
107	        if (owners.isEmpty()) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
116	        Owner owner = this.clinicService.findOwnerById(ownerId);
117	        if (owner == null) {
118	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
119	        }
120	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
121	    }
122	
123	    /**
124	     * Rejects an owner payload that is missing or blank in any of the required fields
125	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
126	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
127	     * value as present; this guard closes that gap so a blank in any required field is
128	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
129	     * the name of each offending field.
130	     */
131	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
132	        List<String> missing = new ArrayList<>();
133	        if (isBlank(ownerFieldsDto.getFirstName())) {
134	            missing.add("firstName");
135	        }
136	        if (isBlank(ownerFieldsDto.getLastName())) {
137	            missing.add("lastName");
138	        }
139	        if (isBlank(normalizedAddress)) {
140	            missing.add("address");
141	        }
142	        if (isBlank(ownerFieldsDto.getCity())) {
143	            missing.add("city");
144	        }
145	        if (isBlank(ownerFieldsDto.getTelephone())) {
146	            missing.add("telephone");
147	        }
148	        if (!missing.isEmpty()) {
149	            throw new MissingOwnerFieldsException(missing);
150	        }
151	    }
152	
153	    private static boolean isBlank(String value) {
154	        return value == null || value.isBlank();
155	    }
156	
157	    /**
158	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
159	     */
160	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
161	
162	    /**
163	     * Required national-number length per country calling code. When the normalized E.164 number
164	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
165	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
166	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
167	     */
168	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
169	        "+61", 9,
170	        "+1", 10);
171	
172	    /**
173	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
174	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
175	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
176	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
177	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
178	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
179	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
180	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
181	     * translates to a 400.
182	     */
183	    private static String normalizeTelephone(String telephone) {
184	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
185	        String e164;
186	        if (cleaned.startsWith("+")) {
187	            e164 = cleaned;
188	        } else {
189	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
190	            e164 = "+61" + national;
191	        }
192	        if (!E164_PATTERN.matcher(e164).matches()) {
193	            throw new InvalidTelephoneException(telephone);
194	        }
195	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
196	            String code = rule.getKey();
197	            if (e164.startsWith(code)) {
198	                int nationalLength = e164.length() - code.length();
199	                if (nationalLength != rule.getValue()) {
200	                    throw new InvalidTelephoneException(telephone);
201	                }
202	                break;
203	            }
204	        }
205	        return e164;
206	    }
207	
208	    /**
209	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
210	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
211	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
212	     */
213	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
214	
215	    /**
216	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
217	     * optional). When present it must be a syntactically valid address; a valid value is
218	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
219	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
220	     */
221	    private static String normalizeEmail(String email) {
222	        if (email == null) {
223	            return null;
224	        }
225	        if (!EMAIL_PATTERN.matcher(email).matches()) {
226	            throw new InvalidEmailException(email);
227	        }
228	        return email.toLowerCase(Locale.ROOT);
229	    }
230	
231	    /**
232	     * Rejects a create whose normalized telephone is already used by another owner. Each
233	     * existing owner's stored telephone is reduced to its E.164 form the same way {@code
234	     * normalizeTelephone} does, so the comparison is on the canonical E.164 value regardless of
235	     * the format each was originally entered in. An existing value that cannot form a valid E.164
236	     * number is skipped rather than colliding. A match is reported via
237	     * {@link DuplicateTelephoneException}, which the exception handler translates to a 409.
238	     */
239	    private void rejectDuplicateTelephone(String normalizedTelephone) {
240	        for (Owner existing : this.clinicService.findAllOwners()) {
241	            String existingE164;
242	            try {
243	                existingE164 = normalizeTelephone(existing.getTelephone());
244	            } catch (InvalidTelephoneException ex) {
245	                continue;
246	            }
247	            if (normalizedTelephone.equals(existingE164)) {
248	                throw new DuplicateTelephoneException(normalizedTelephone);
249	            }
250	        }
251	    }
252	
253	    /**
254	     * Rejects a create whose lower-cased email is already used by another owner. The candidate
255	     * email is already normalized to lower case by {@code normalizeEmail}; each existing owner's
256	     * email is lower-cased the same way for the comparison, so the match is case-insensitive
257	     * regardless of the case each was originally entered in. An existing owner with no email is
258	     * skipped. A {@code null} candidate email is not checked, since email is optional. A match is
259	     * reported via {@link DuplicateEmailException}, which the exception handler translates to a 409.
260	     */
261	    private void rejectDuplicateEmail(String normalizedEmail) {
262	        if (normalizedEmail == null) {
263	            return;
264	        }
265	        for (Owner existing : this.clinicService.findAllOwners()) {
266	            String existingEmail = existing.getEmail();
267	            if (existingEmail != null && normalizedEmail.equals(existingEmail.toLowerCase(Locale.ROOT))) {
268	                throw new DuplicateEmailException(normalizedEmail);
269	            }
270	        }
271	    }
272	
273	    /**
274	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
275	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
276	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
277	     * spacing do not defeat the duplicate-household check.
278	     */
279	    private static String collapse(String value) {
280	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
281	    }
282	
283	    /**
284	     * Normalizes an owner's address into a canonical form applied on every create: leading and
285	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
286	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
287	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
288	     * and returned, and is the form every address comparison (duplicate-household detection and the
289	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
290	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
291	     * so normalizing an already-normalized address is a no-op.
292	     */
293	    private static String normalizeAddress(String address) {
294	        if (address == null) {
295	            return "";
296	        }
297	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
298	        if (collapsed.isEmpty()) {
299	            return "";
300	        }
301	        String[] tokens = collapsed.split(" ");
302	        StringBuilder sb = new StringBuilder(collapsed.length());
303	        for (int i = 0; i < tokens.length; i++) {
304	            String token = tokens[i];
305	            switch (token) {
306	                case "ST" -> token = "STREET";
307	                case "RD" -> token = "ROAD";
308	                case "AVE" -> token = "AVENUE";
309	                default -> {
310	                }
311	            }
312	            if (i > 0) {
313	                sb.append(' ');
314	            }
315	            sb.append(token);
316	        }
317	        return sb.toString();
318	    }
319	
320	    /**
321	     * Rejects a create that would place a second owner in the same household as an existing one -
322	     * i.e. another owner already has the same {@code lastName} and the same {@code address},
323	     * compared case-insensitively with collapsed whitespace. The caller can opt in to sharing a
324	     * household by setting {@code sharesHousehold} true, in which case this check is skipped. A
325	     * match is reported via {@link DuplicateHouseholdException}, which the exception handler
326	     * translates to a 409.
327	     */
328	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
329	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
330	            return;
331	        }
332	        String lastName = collapse(ownerFieldsDto.getLastName());
333	        for (Owner existing : this.clinicService.findAllOwners()) {
334	            if (lastName.equals(collapse(existing.getLastName()))
335	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
336	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
337	            }
338	        }
339	    }
340	
341	    /**
342	     * Builds the {@code customerCode} for a newly created owner, formatted
343	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters of
344	     * {@code city}, {@code LAST3} the upper-cased first three letters of {@code lastName}, and
345	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of
346	     * owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
347	     */
348	    private String nextCustomerCode(String city, String lastName) {
349	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
350	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
351	        int sequence = 1;
352	        for (Owner existing : this.clinicService.findAllOwners()) {
353	            if (city.equalsIgnoreCase(existing.getCity())) {
354	                sequence++;
355	            }
356	        }
357	        return String.format("%s-%s-%04d", city3, last3, sequence);
358	    }
359	
360	    /**
361	     * Builds the {@code membershipNumber} for a newly created owner, formatted
362	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
363	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
364	     */
365	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
366	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
367	    }
368	
369	    /**
370	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
371	     * {@code address} - the same pair used to detect a shared household. Because it is a pure
372	     * function of that pair (upper-case hex of SHA-256 over the two collapsed values), every owner
373	     * in the same household - whether created first or joining later via {@code sharesHousehold} -
374	     * receives the identical, non-blank identifier without needing to read any other owner's value.
375	     */
376	    private static String householdIdFor(String lastName, String address) {
377	        String key = collapse(lastName) + "\n" + normalizeAddress(address);
378	        try {
379	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
380	            StringBuilder sb = new StringBuilder(32);
381	            for (int i = 0; i < 8; i++) {
382	                sb.append(String.format("%02X", digest[i]));
383	            }
384	            return sb.toString();
385	        } catch (NoSuchAlgorithmException ex) {
386	            throw new IllegalStateException("SHA-256 not available", ex);
387	        }
388	    }
389	
390	    /**
391	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
392	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
393	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
394	     */
395	    private int countNamesakes(String firstName, String lastName) {
396	        int count = 0;
397	        for (Owner existing : this.clinicService.findAllOwners()) {
398	            if (firstName.equalsIgnoreCase(existing.getFirstName())
399	                && lastName.equalsIgnoreCase(existing.getLastName())) {
400	                count++;
401	            }
402	        }
403	        return count;
404	    }
405	
406	    /**
407	     * Counts the members of the household the new owner will belong to, as it stands after this
408	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
409	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
410	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
411	     * stored on the owner as its {@code householdMemberCount}.
412	     */
413	    private int countHouseholdMembers(String householdId) {
414	        int count = 1;
415	        for (Owner existing : this.clinicService.findAllOwners()) {
416	            if (householdId.equals(existing.getHouseholdId())) {
417	                count++;
418	            }
419	        }
420	        return count;
421	    }
422	
423	    /**
424	     * The membership level ceiling assigned on create; level 4 is reserved for tenure and so is
425	     * never reached here.
426	     */
427	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
428	
429	    /**
430	     * Computes the numeric {@code membershipLevel} for a newly created owner. It starts at 1,
431	     * gains 1 when an email is present, gains 1 when the owner's {@code namesakeCount} is 0, and
432	     * is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure). Evaluated after
433	     * the owner's email and namesakeCount have been set.
434	     */
435	    private static int membershipLevelFor(Owner owner) {
436	        int level = 1;
437	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
438	            level++;
439	        }
440	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
441	            level++;
442	        }
443	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
444	    }
445	
446	    /**
447	     * The maximum number of owners any single city may contain. A create whose city already
448	     * holds this many owners is rejected.
449	     */
450	    private static final int CITY_CAPACITY = 50;
451	
452	    /**
453	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
454	     * compared case-insensitively - the same way the city is matched when building the
455	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
456	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
457	     * translates to a 409.
458	     */
459	    private void rejectCityAtCapacity(String city) {
460	        int count = 0;
461	        for (Owner existing : this.clinicService.findAllOwners()) {
462	            if (city.equalsIgnoreCase(existing.getCity())) {
463	                count++;
464	            }
465	        }
466	        if (count >= CITY_CAPACITY) {
467	            throw new CityAtCapacityException(city);
468	        }
469	    }
470	
471	    /**
472	     * The maximum number of owners that may be created on any single day (by
473	     * {@code registrationDate}). A create attempted once this many owners already carry the
474	     * current day's registration date is rejected.
475	     */
476	    private static final int DAILY_OWNER_LIMIT = 100;
477	
478	    /**
479	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
480	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
481	     * The count reflects the state prior to this create. When the limit is reached the create is
482	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
483	     * to a 429 Too Many Requests.
484	     */
485	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
486	        int count = 0;
487	        for (Owner existing : this.clinicService.findAllOwners()) {
488	            if (registrationDate.equals(existing.getRegistrationDate())) {
489	                count++;
490	            }
491	        }
492	        if (count >= DAILY_OWNER_LIMIT) {
493	            throw new DailyOwnerLimitExceededException();
494	        }
495	    }
496	
497	    /**
498	     * The number of owners that must already carry a given {@code registrationDate} before a
499	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
500	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
501	     */
502	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
503	
504	    /**
505	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
506	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
507	     * have already been created for that date, otherwise false. The count reflects the state prior
508	     * to this create, matching how the daily-limit rule accumulates.
509	     */
510	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
511	        int count = 0;
512	        for (Owner existing : this.clinicService.findAllOwners()) {
513	            if (registrationDate.equals(existing.getRegistrationDate())) {
514	                count++;
515	            }
516	        }
517	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
518	    }
519	
520	    /**
521	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is
522	     * advanced to the following Monday; a weekday is returned unchanged. This is applied to the
523	     * effective registration date - whether supplied in the request or defaulted to the server
524	     * date - so the stored {@code registrationDate}, and everything derived from it, always falls
525	     * on a business day.
526	     */
527	    private static LocalDate toBusinessDay(LocalDate date) {
528	        return switch (date.getDayOfWeek()) {
529	            case SATURDAY -> date.plusDays(2);
530	            case SUNDAY -> date.plusDays(1);
531	            default -> date;
532	        };
533	    }
534	
535	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
536	    @Override
537	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
538	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
539	        rejectMissingOrBlankFields(ownerFieldsDto, normalizedAddress);
540	        rejectDuplicateHousehold(ownerFieldsDto, normalizedAddress);
541	        rejectCityAtCapacity(ownerFieldsDto.getCity());
542	        HttpHeaders headers = new HttpHeaders();
543	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
544	        owner.setAddress(normalizedAddress);
545	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
546	        rejectDuplicateTelephone(normalizedTelephone);
547	        owner.setTelephone(normalizedTelephone);
548	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
549	        rejectDuplicateEmail(normalizedEmail);
550	        owner.setEmail(normalizedEmail);
551	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
552	        LocalDate registrationDate = toBusinessDay(effectiveDate);
553	        rejectDailyOwnerLimit(registrationDate);
554	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
555	        owner.setRegistrationDate(registrationDate);
556	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
557	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
558	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
559	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
560	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
561	        owner.setMembershipLevel(membershipLevelFor(owner));
562	        this.clinicService.saveOwner(owner);
563	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
564	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
565	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
566	        headers.setLocation(UriComponentsBuilder.newInstance()
567	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
568	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
569	    }
570	
571	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
572	    @Override
573	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
574	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
575	        if (currentOwner == null) {
576	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
577	        }
578	        currentOwner.setAddress(ownerFieldsDto.getAddress());
579	        currentOwner.setCity(ownerFieldsDto.getCity());
580	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
581	        currentOwner.setLastName(ownerFieldsDto.getLastName());
582	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
583	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
584	        this.clinicService.saveOwner(currentOwner);
585	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
586	    }
587	
588	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
589	    @Transactional
590	    @Override
591	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
592	        Owner owner = this.clinicService.findOwnerById(ownerId);
593	        if (owner == null) {
594	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
595	        }
596	        this.clinicService.deleteOwner(owner);
597	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
598	    }
599	
600	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
601	    @Override
602	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
603	        Owner owner = this.clinicService.findOwnerById(ownerId);
604	        if (owner == null) {
605	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
606	        }
607	        HttpHeaders headers = new HttpHeaders();
608	        Pet pet = petMapper.toPet(petFieldsDto);
609	        owner.setId(ownerId);
610	        pet.setOwner(owner);
611	        pet.getType().setName(null);
612	        this.clinicService.savePet(pet);
613	        PetDto petDto = petMapper.toPetDto(pet);
614	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
615	            .buildAndExpand(pet.getId()).toUri());
616	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
617	    }
618	
619	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
620	    @Override
621	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
622	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
623	        if (currentOwner != null) {
624	            Pet currentPet = this.clinicService.findPetById(petId);
625	            if (currentPet != null) {
626	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
627	                currentPet.setName(petFieldsDto.getName());
628	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
629	                this.clinicService.savePet(currentPet);
630	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
631	            }
632	        }
633	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
634	    }
635	
636	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
637	    @Override
638	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
639	        HttpHeaders headers = new HttpHeaders();
640	        Visit visit = visitMapper.toVisit(visitFieldsDto);
641	        Pet pet = new Pet();
642	        pet.setId(petId);
643	        visit.setPet(pet);
644	        this.clinicService.saveVisit(visit);
645	        VisitDto visitDto = visitMapper.toVisitDto(visit);
646	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
647	            .buildAndExpand(visit.getId()).toUri());
648	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
649	    }
650	
651	
652	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
653	    @Override
654	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
655	        Owner owner = this.clinicService.findOwnerById(ownerId);
656	        if (owner != null) {
657	            Pet pet = owner.getPet(petId);
658	            if (pet != null) {
659	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
660	            }
661	        }
662	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
663	    }
664	}
